//! `docs/deckd-api.md` is generated, and this row is what keeps it that way
//! (HOST-CONTRACT-W7 §5).
//!
//! The same shape as `gate_ratchet`: a fact written twice — once in the Rust
//! types and the dispatch table, once in a checked-in Markdown file — with a
//! test that fails by name when only one of them moved, and a failure message
//! that is the command to fix it. Without it the document is a second source
//! of truth that nothing checks, which is the thing a generated file exists
//! to avoid.
//!
//! The other half of the claim — that what the generator is handed is what
//! `GET /v1/schema` actually serves, rather than a second object assembled
//! the same way — is `deckd::api::http`'s
//! `the_tcp_door_needs_a_token_for_everything_but_info`, which compares the
//! served body with `apidoc::schema()` in the same process.
use std::path::PathBuf;

/// The repository root: this crate lives at `<repo>/host/crates/deckd`.
fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .canonicalize()
        .expect("the crate sits three levels under the repository root")
}

#[test]
fn the_checked_in_api_document_is_what_the_schema_produces() {
    let path = repo_root().join("docs/deckd-api.md");
    let checked_in = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e} — generate it with:\n  {}",
            path.display(),
            deckd::apidoc::REGENERATE
        )
    });
    let generated = deckd::apidoc::render(&deckd::apidoc::schema());
    if checked_in == generated {
        return;
    }
    // Name the first line that differs: a 700-line diff in an assertion
    // message tells nobody anything, and the point of the row is that the
    // next step is one command.
    let first_difference = checked_in
        .lines()
        .zip(generated.lines())
        .enumerate()
        .find(|(_, (a, b))| a != b)
        .map(|(n, (a, b))| format!("line {}:\n  checked in: {a}\n  schema says: {b}", n + 1))
        .unwrap_or_else(|| {
            format!(
                "the files agree for {} lines and then one of them ends ({} vs {} lines)",
                checked_in.lines().count().min(generated.lines().count()),
                checked_in.lines().count(),
                generated.lines().count()
            )
        });
    panic!(
        "docs/deckd-api.md is not what /v1/schema produces.\n\n{first_difference}\n\n\
         The document is generated; do not edit it. Regenerate it with:\n\n  {}\n",
        deckd::apidoc::REGENERATE
    );
}

/// The document is only useful if it is complete: every method the daemon
/// answers has a row, and every type a row names has an entry to link to.
/// A generator that quietly dropped half the table would still match a
/// checked-in file generated by the same bug.
#[test]
fn the_document_carries_every_method_and_every_type_the_schema_names() {
    let schema = deckd::apidoc::schema();
    let doc = deckd::apidoc::render(&schema);
    let methods = schema["methods"].as_array().expect("the dispatch table");
    assert!(methods.len() > 50, "only {} methods", methods.len());
    for method in methods {
        let name = method["name"].as_str().unwrap();
        assert!(
            doc.contains(&format!("| `{name}` |")),
            "`{name}` has no row in docs/deckd-api.md"
        );
    }
    for top in ["snapshot", "event", "request", "link_event", "error"] {
        for name in schema[top]["$defs"]
            .as_object()
            .into_iter()
            .flat_map(|defs| defs.keys())
        {
            assert!(
                doc.contains(&format!("### `{name}`")),
                "the type `{name}` (from `{top}`) has no entry"
            );
        }
    }
}
